html:
{% set company = frappe.db.get_default("company") or frappe.db.get_single_value("Global Defaults", "default_company") %}
{% set company_logo = frappe.db.get_value("Company", company, "company_logo") if company else "" %}


{% set jo = None %}

{% set dn_print = frappe.call("apc_operations.shipping.services.loading_dn_print_service.get_print_context_for_erpnext_dn", erpnext_dn_name=doc.name) %}

<style>
  @page {
    size: A4;
    margin: 8mm;
  }

  body {
    margin: 0;
    padding: 0;
    font-family: Arial, sans-serif;
    color: #000;
  }

  .dn-page {
    width: 100%;
    min-height: 277mm;
    box-sizing: border-box;
    font-family: Arial, sans-serif;
    color: #000;
    font-size: 12px;
  }

  .dn-title {
    text-align: center;
    font-size: 19px;
    font-weight: 700;
    line-height: 1;
    margin: 0 0 3px 0;
    text-transform: uppercase;
  }

  .dn-main {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    border: 1px solid #000;
  }

  .dn-main td,
  .dn-main th {
    border: 1px solid #000;
    vertical-align: top;
    white-space: normal;
    overflow-wrap: anywhere;
    word-break: break-word;
  }

  .company-block {
    padding: 6px 7px 4px 7px;
    height: 175px;
  }

  .company-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .company-table td {
    border: none;
    vertical-align: top;
  }

  .logo-cell {
    width: 285px;
  }

  .logo-cell img {
    width: 260px;
    height: 165px;
    object-fit: contain;
    display: block;
  }

  .company-name {
    font-size: 14px;
    font-weight: 700;
    line-height: 1.15;
    margin-bottom: 4px;
    text-transform: uppercase;
  }

  .company-line {
    font-size: 12px;
    line-height: 1.25;
  }

  .doc-info {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .doc-info td {
    border-left: none;
    border-right: none;
    border-top: none;
    border-bottom: 1px solid #000;
    padding: 3px 5px;
    height: 26px;
    font-size: 12px;
    line-height: 1.15;
  }

  .doc-info tr:last-child td {
    border-bottom: none;
  }

  .doc-info .info-label {
    width: 45%;
  }

  .doc-info .info-value {
    font-weight: 700;
  }

  .party-cell {
    height: 190px;
    padding: 5px 6px;
  }

  .party-title {
    font-size: 12px;
    margin-bottom: 4px;
  }

  .party-name {
    font-size: 14px;
    font-weight: 700;
    line-height: 1.25;
  }

  .party-text {
    font-size: 12px;
    line-height: 1.35;
  }

  .transport-info {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .transport-info td {
    border-left: none;
    border-right: none;
    border-top: none;
    border-bottom: 1px solid #000;
    padding: 4px 5px;
    height: 28px;
    font-size: 12px;
    line-height: 1.15;
  }

  .transport-info tr:last-child td {
    border-bottom: none;
  }

  .transport-info .info-label {
    width: 45%;
  }

  .goods-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .goods-table th,
  .goods-table td {
    border: 1px solid #000;
    padding: 4px 5px;
    font-size: 11px;
    line-height: 1.25;
    vertical-align: top;
    white-space: normal;
    overflow-wrap: anywhere;
    word-break: break-word;
  }

  .goods-table th {
    text-align: center;
    font-weight: 400;
  }

  .goods-row td {
    vertical-align: top;
  }

  .goods-table .goods-body td {
    height: 340px;
  }

  .center {
    text-align: center;
  }

  .right {
    text-align: right;
  }

  .bold {
    font-weight: 700;
  }

  .product-name {
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    overflow-wrap: anywhere;
    word-break: break-word;
  }

  .seal-line,
  .batch-line {
    display: block;
    margin-top: 3px;
    font-size: 10px;
    line-height: 1.2;
    overflow-wrap: anywhere;
    word-break: break-word;
  }

  .sub-product {
    display: block;
    margin-top: 5px;
    font-style: italic;
    font-size: 12px;
    font-weight: 400;
  }

  .vat-text {
    margin-top: 32px;
    text-align: right;
    font-size: 14px;
    font-weight: 700;
    font-style: italic;
  }

  .total-row td {
    height: 18px;
    padding-top: 2px;
    padding-bottom: 2px;
  }

  .bottom-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    border-left: 1px solid #000;
    border-right: 1px solid #000;
    border-bottom: 1px solid #000;
  }

  .bottom-table td {
    border: 1px solid #000;
    padding: 6px 6px;
    height: 48px;
    vertical-align: top;
    font-size: 12px;
  }

  .sign-cell {
    text-align: right;
  }

  .sign-company {
    font-size: 12px;
    font-weight: 700;
    margin-bottom: 25px;
  }

  .sign-title {
    font-size: 11px;
  }

  .generated {
    text-align: center;
    font-size: 12px;
    margin-top: 8px;
  }

  .stamp-area {
    margin-top: 4px;
    margin-left: 85px;
    width: 100px;
    height: 100px;
  }

  .stamp-area img {
    width: 100px;
    height: 100px;
    object-fit: contain;
    opacity: 0.9;
  }

  @media print {
    .dn-page {
      page-break-after: avoid;
    }
  }
</style>

<div class="dn-page">

  <div class="dn-title">DELIVERY NOTE</div>

  <table class="dn-main">
    <tr>
      <td style="width:50%;" class="company-block" rowspan="2">
        <table class="company-table">
          <tr>
            <td class="logo-cell">
              {% if company_logo %}
                <img src="{{ company_logo }}" alt="Company Logo">
              {% else %}
                <img src="/files/AP_Logo.webp" alt="Company Logo" onerror="this.style.display='none'">
              {% endif %}
            </td>
            <td>
              <div class="company-name">ASIA PETROCHEMICALS LLC OPC</div>
              <div class="company-line">Plot # A 23 B, Al Jazeera Industrial Area</div>
              <div class="company-line">TRN : {{ (dn_print.company_trn if dn_print else None) or "100283348900003" }}</div>
              <div class="company-line">Emirate : Ras Al-Khaimah</div>
              <div class="company-line">E-Mail : info@asia-petrochem.com</div>
            </td>
          </tr>
        </table>
      </td>

      <td style="width:25%;">
        <table class="doc-info">
          <tr>
            <td>
              <div>Delivery Note No.</div>
              <div class="info-value">{{ doc.name }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Supplier's Ref.</div>
              <div class="info-value">{{ (dn_print.supplier_ref if dn_print else None) or doc.name or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Buyer’s Order No.</div>
              <div class="info-value">{{ (dn_print.job_order if dn_print else None) or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Despatch Document No.</div>
              <div class="info-value">{{ (dn_print.security_inspection if dn_print else None) or "-" }}</div>
            </td>
          </tr>
<tr>
            <td>
              <div>Terms of Delivery</div>
              <div class="info-value">{{ (dn_print.terms_of_delivery if dn_print else None) or "DELIVERED" }}</div>
            </td>
          </tr>
        </table>
      </td>

      <td style="width:25%;">
        <table class="doc-info">
          <tr>
            <td>
              <div>Date of delivery</div>
              <div class="info-value">
                {{ frappe.utils.formatdate(doc.loading_date) if doc.loading_date else frappe.utils.formatdate(doc.creation) }}
              </div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Mode/Terms of Payment</div>
              <div class="info-value">{{ (dn_print.payment_terms if dn_print else None) or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Other Reference(s)</div>
              <div class="info-value">{{ (dn_print.other_reference if dn_print else None) or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Buyer's Order Date</div>
              <div class="info-value">
                {{ frappe.utils.formatdate(dn_print.job_order_date) if dn_print and dn_print.job_order_date else "-" }}
              </div>
            </td>
          </tr></table>
      </td>
    </tr>

    <tr></tr>

    <tr>
      <td class="party-cell" colspan="3">
        <div class="party-title">Buyer</div>
        <div class="party-name">{{ (dn_print.buyer_name if dn_print else None) or doc.customer_name or doc.buyer or doc.customer or "-" }}</div>
        <div class="party-text">
          {{ (dn_print.buyer_address if dn_print else "") or "" }}
        </div>

        {% if doc.emirate or doc.country or doc.trn or doc.place_of_supply %}
          <div class="party-text">
            {% if doc.emirate %}Emirate&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: {{ doc.emirate }}<br>{% endif %}
            {% if doc.country %}Country&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: {{ doc.country }}<br>{% endif %}
            {% if doc.trn %}TRN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: {{ doc.trn }}<br>{% endif %}
            {% if doc.place_of_supply %}Place of supply&nbsp;: {{ doc.place_of_supply }}{% endif %}
          </div>
        {% endif %}
      </td>

      </tr>
  </table>

  <table class="goods-table">
    <thead>
      <tr>
        <th style="width:5%;">Sl<br>No.</th>
        <th style="width:11%;">Marks & Nos./<br>Container No.</th>
        <th style="width:11%;">No. & Kind<br>of Pkgs.</th>
        <th style="width:12%;">Packaging</th>
        <th style="width:50%;">Description of Goods</th>
        <th style="width:11%;">Quantity</th>
      </tr>
    </thead>

    <tbody>
      {% set marks = (dn_print.container_summary if dn_print else None) or doc.container_number or "-" %}
      {% set pkgs = dn_print.no_and_kind_of_packages if dn_print else (doc.package_type or doc.no_and_kind_of_packages or "-") %}
      {% set product_lines = (dn_print.print_rows if dn_print and dn_print.print_rows else (dn_print.do_items if dn_print else [])) %}
      {% if product_lines %}
        {% for row in product_lines %}
        <tr class="goods-row{% if loop.last and product_lines|length == 1 %} goods-body{% endif %}">
          <td class="center">{{ loop.index }}</td>
          <td class="center">
            {{ row.container_number if row.container_number is defined and row.container_number else (row.marks_and_nos if row.marks_and_nos is defined else (marks if loop.first else "")) }}
            {% if row.seal_number %}<span class="seal-line">Seal: {{ row.seal_number }}</span>{% endif %}
          </td>
          <td class="center">{{ row.no_and_kind_of_packages if row.no_and_kind_of_packages is defined else (pkgs if loop.first else "") }}</td>
          <td class="center">{{ row.packaging or (dn_print.packaging_type if dn_print else None) or "-" }}</td>
          <td>
            <div class="product-name">{{ row.description or doc.material_description or doc.product_name or "-" }}</div>
            {% if loop.first and (doc.vehicle_type or doc.container_type) %}
              <span class="sub-product">{{ doc.vehicle_type or doc.container_type }}</span>
            {% endif %}
            {% if loop.first and dn_print and dn_print.net_weight_kg %}
              <div>Loaded Net Wt: {{ dn_print.net_weight_kg }} kg</div>
            {% endif %}
            {% for batch in (row.batch_lines if row.batch_lines is defined else []) %}
              <span class="batch-line">
                Batch: {{ batch.batch }}
                {% if batch.coa %}<br>COA: {{ batch.coa }}{% endif %}
                {% if batch.qty %}<br>Loaded: {{ batch.qty }} {{ batch.uom }}{% if batch.qty_kg %} ({{ batch.qty_kg }} kg){% endif %}{% endif %}
              </span>
            {% endfor %}
            {% if row.tare_weight %}<div>Tare Wt: {{ row.tare_weight }} kg</div>{% endif %}
              {% if row.gross_weight %}<div>Gross Wt: {{ row.gross_weight }} kg</div>{% endif %}
              {% if row.weighbridge_net_kg %}<div>Weighbridge Net: {{ row.weighbridge_net_kg }} kg</div>{% endif %}
              {% if row.actual_cargo_gross_kg %}<div>Actual Cargo Gross: {{ row.actual_cargo_gross_kg }} kg</div>{% endif %}
              {% if row.actual_loaded_packaging_tare_kg %}<div>Loaded Packaging Tare: {{ row.actual_loaded_packaging_tare_kg }} kg</div>{% endif %}
              {% if row.estimated_actual_product_net_kg %}<div>Actual Product Net: {{ row.estimated_actual_product_net_kg }} kg</div>{% endif %}
              {% if row.actual_product_mt_display %}<div>Actual Product MT: {{ row.actual_product_mt_display }}</div>{% endif %}
            {% if loop.last %}
              {% if doc.vat_text %}
                <div class="vat-text">{{ doc.vat_text }}</div>
              {% else %}
                <div class="vat-text">VAT 5%</div>
              {% endif %}
            {% endif %}
          </td>
          <td class="center bold">{{ row.qty_display or row.qty or "-" }}{% if not row.qty_display and row.qty %} {{ row.uom or "" }}{% endif %}</td>
        </tr>
        {% endfor %}
      {% else %}
        <tr class="goods-body">
          <td class="center">1</td>
          <td class="center">{{ marks }}</td>
          <td class="center">{{ pkgs }}</td>
          <td class="center">{{ (dn_print.packaging_type if dn_print else None) or "-" }}</td>
          <td>
            <div class="product-name">{{ doc.material_description or doc.product_name or "-" }}</div>
            {% if doc.vat_text %}<div class="vat-text">{{ doc.vat_text }}</div>{% else %}<div class="vat-text">VAT 5%</div>{% endif %}
          </td>
          <td class="center bold">{{ dn_print.loaded_qty_display if dn_print else (doc.quantity or "-") }}</td>
        </tr>
      {% endif %}

      <tr class="total-row">
        <td></td>
        <td></td>
        <td></td>
        <td class="right">Total</td>
        <td class="center bold">{{ dn_print.loaded_qty_display if dn_print else ((doc.quantity or "-") + " " + (doc.uom or "")) }}</td>
      </tr>

      <tr class="total-row">
        <td></td>
        <td></td>
        <td></td>
        <td class="right">Total Net Weight (kg)</td>
        <td class="center bold">{{ dn_print.total_net_weight_kg if dn_print and dn_print.total_net_weight_kg else "-" }}</td>
      </tr>

      <tr class="total-row">
        <td></td>
        <td></td>
        <td></td>
        <td class="right">E. &amp; O.E</td>
        <td></td>
      </tr>
    </tbody>
  </table>

  <table class="bottom-table">
    <tr>
      <td style="width:50%;">
        Recd. in Good Condition
      </td>

      <td style="width:50%;" class="sign-cell">
        <div class="sign-company">for ASIA PETROCHEMICALS LLC OPC</div>
        <div class="sign-title">Authorised Signatory</div>
      </td>
    </tr>
  </table>

  <div class="generated">This is a Computer Generated Document</div>

  <div class="stamp-area">
    {% if company_logo %}
      <img src="{{ company_logo }}" alt="Company Stamp">
    {% else %}
      <img src="/files/AP_Logo.webp" alt="Company Stamp" onerror="this.style.display='none'">
    {% endif %}
  </div>

</div>
